  /**
   * <!-- begin-user-doc -->
   * <!-- end-user-doc -->
   * <!-- end-model-doc -->
   * <!-- begin-model-doc -->
   * Summary:
   * Restores the latest successfully placed pipe to the front of the queue and removes it from the board.
   * Algorithm:
   * 1. Check whether the placement history stack contains at least one cell.
   * 2. If not, return false without modifying state.
   * 3. Otherwise pop the latest placed FillableCell from the history.
   * 4. Clear that cell from the map using its stored coordinate.
   * 5. Push the removed pipe back to the front of the queue.
   * 6. Increment the step counter by one.
   * 7. Return true.
   * Related Features:
   * - numOfSteps: incremented on successful undo.
   * - cellStack: provides the most recent placement.
   * - map: clears the reverted placement.
   * - pipeQueue: receives the restored pipe at the front.
   * Related Classes: CellStack, Map, PipeQueue, FillableCell, Coordinate, Pipe
   * Input:
   * - None.
   * Output:
   * - boolean: true if an undo was performed, false if there was no previous placement to undo.
   * Pre-condition:
   * - The Game object has been initialized.
   * Post-condition:
   * - On success: the last placed pipe is removed from the board, returned to the front of the queue, and step count increases by 1.
   * - On failure: the board, queue, history, and step count remain unchanged.
   * <!-- end-model-doc -->
   * @model annotation="http://www.ustb.edu.cn/sei/mde/EnhancedCodeGen generated='true'"
   * @generated NOT
   */
  public boolean undoStep()
  {
    CellStack stack = getCellStack();
    if (stack == null || stack.getStack().isEmpty())
    {
      return false;
    }

    FillableCell cell = stack.pop();
    if (cell == null)
    {
      return false;
    }

    Map map = getMap();
    if (map != null && cell.getCoord() != null)
    {
      map.undo(cell.getCoord());
    }

    PipeQueue queue = getPipeQueue();
    if (queue != null && cell.getPipe() != null)
    {
      queue.undo(cell.getPipe());
    }

    setNumOfSteps(getNumOfSteps() + 1);
    return true;
    
  }

